insert into public.site_settings (key, value) values ('global', '{"name": "Dr. Anameka S Panda", "tagline": "Align Your Inner Cosmos \u2014 Transform Your Outer World", "heroHeadline": "Align Your Cosmos. Transform Your World. Create a Better Tomorrow.", "heroSubheading": "Integrated occult science and vibrational energy healing for Health, Wealth, and Relationships with Dr. Anameka S Panda.", "shortBio": "Dr. Anameka S Panda is an occult practitioner, graphologist, Vedic astrologer, Medical Astrology & Vastu consultant based in Bhubaneswar. She integrates Jyotish astrology, non-invasive Vastu, bio-energetic healing, and handwriting science for individuals, families, and business leaders worldwide.", "serviceArea": "Based in Bhubaneswar, Odisha. Consultations online worldwide and in person", "hours": "By appointment", "logoUrl": "/brand/logo-a.svg", "portraitUrl": "/brand/anameka-s-panda-portrait.webp", "ogImageUrl": ""}'::jsonb) on conflict (key) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('vedic-astrology','Vedic Astrology','A reading of your birth chart in the Jyotish tradition, covering planetary periods and timing questions such as career and marriage.','Orbit','Vedic astrology, or Jyotish, is one of the oldest systems of astrology still in practice. A consultation uses your date, time and place of birth to prepare a chart, which then becomes the starting point for a structured conversation about the areas of life you want to think through.','Jyotish maps the positions of the planets and lunar mansions (nakshatras) at the moment of birth. Practitioners read the chart through houses, signs, planetary periods (dashas) and transits. It is a traditional interpretive framework, not an empirical science, and a good consultation is clear about that.','Dr. Anameka prepares your chart in advance, studies the questions you have shared, and reads the chart with those questions in mind. The session focuses on your priorities rather than a general recitation of every placement.','People at a crossroads in career, relationships or family life; those asking timing questions such as career moves or marriage; and anyone who values traditional Indian knowledge systems as part of how they plan.','[{"title": "Share your birth details", "body": "Date, exact time and place of birth. If the time is uncertain, mention it so the reading can account for that."}, {"title": "Tell us your questions", "body": "Two or three focused questions make for a far more useful session than a general reading."}, {"title": "Consultation", "body": "An unhurried session online or in person, with time for your follow-up questions."}, {"title": "Summary and suggestions", "body": "Key observations and any optional practices discussed are summarised so you can refer back to them."}]'::jsonb,'["A structured way to reflect on decisions and timing", "Time with an experienced practitioner who listens to your situation", "Suggestions that are practical and optional, never coercive"]'::jsonb,'["Astrology is a traditional belief system; outcomes are not guaranteed", "It does not replace medical, legal, financial or psychological advice", "Accuracy depends on the accuracy of the birth time provided"]'::jsonb,'[{"q": "What details do I need for a Vedic astrology consultation?", "a": "Your date of birth, the most accurate time of birth you have, and your place of birth. A list of the questions you most want to explore helps the session stay focused."}, {"q": "What if I don''t know my exact birth time?", "a": "Let us know when you book. Some observations depend heavily on birth time, so the consultation will say which parts of the reading are less certain."}, {"q": "Can astrology predict exactly what will happen?", "a": "No responsible practitioner can promise that. Consultations are offered as guidance and reflection, and the decisions remain yours."}, {"q": "Is the consultation available online?", "a": "Yes. Consultations can be held online or in person, whichever suits you."}]'::jsonb,'Vedic Astrology Consultation | Dr. Anameka S Panda','Personalised Vedic astrology (Jyotish) consultations with Dr. Anameka S Panda, online or in person. Thoughtful birth-chart guidance for career, family and life decisions.',10,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('vastu-consultation','Vastu Consultation','Guidance on the layout, orientation and use of homes and workplaces according to the principles of Vastu Shastra.','Compass','Vastu Shastra is the traditional Indian discipline of space and architecture. A Vastu consultation looks at how a home, office, shop or factory is oriented and arranged, and offers suggestions for planning new spaces or adjusting existing ones.','Vastu considers directions, the placement of rooms and entrances, the flow of light and movement, and the use of the five elements. Suggestions can range from planning advice for new construction to simple rearrangements in an existing space.','The consultation begins with a floor plan and the orientation of the property. Dr. Anameka reviews the layout, discusses how the space is actually used, and identifies the areas that matter most to you.','Families planning, buying or renovating a home; business owners setting up offices, shops or factories; and anyone who wants their space to reflect Vastu principles.','[{"title": "Send the floor plan", "body": "A floor plan with the north direction marked, plus photographs if available."}, {"title": "Discuss your priorities", "body": "Explain how you use the space and what concerns you most."}, {"title": "Site review", "body": "An online review of plans and photographs, or a visit where offline consultation is arranged."}, {"title": "Recommendations", "body": "Prioritised suggestions, separating simple adjustments from larger changes."}]'::jsonb,'["Clarity on how Vastu principles apply to your specific space", "Prioritised suggestions you can act on gradually", "Useful input at the planning stage, before construction costs are committed"]'::jsonb,'["Vastu is a traditional discipline; specific outcomes cannot be guaranteed", "Structural, electrical or legal matters must always be checked by qualified professionals", "Recommendations depend on the accuracy of the plans shared"]'::jsonb,'[{"q": "Do I need to demolish or rebuild to follow Vastu?", "a": "Usually not. Many suggestions involve placement, usage and arrangement. Where structural change is discussed, it is presented as an option, and non-invasive alternatives are explained."}, {"q": "Can Vastu consultation be done online?", "a": "Yes, using floor plans, the north orientation and photographs. Site visits can be arranged for offline consultations."}, {"q": "Is Vastu only for homes?", "a": "No. It is applied to offices, shops, clinics, factories and other commercial spaces as well."}]'::jsonb,'Vastu Consultation for Homes & Businesses | Dr. Anameka S Panda','Vastu Shastra consultation for homes, offices and commercial spaces. Practical, prioritised guidance from plans and site reviews, online or in person.',20,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('non-invasive-vastu','Non-Invasive Vastu','Vastu corrections that work with your existing home: no demolition, no breaking, no structural changes.','Home','Many people live or work in spaces they cannot rebuild: rented homes, apartments, established offices. Non-invasive Vastu focuses on suggestions that respect the structure as it stands.','Instead of moving walls or entrances, non-invasive Vastu works through the use of rooms, placement of furniture and objects, colours, lighting and other reversible adjustments.','The existing layout is reviewed and the suggestions are limited to changes you can make without construction. Each suggestion is explained so you understand the reasoning behind it.','Tenants, apartment residents, businesses in leased premises, and anyone who wants Vastu guidance without the cost and disruption of construction.','[{"title": "Share the current layout", "body": "Floor plan, north direction and photographs of the main areas."}, {"title": "Identify constraints", "body": "Tell us what can and cannot be changed in the space."}, {"title": "Review", "body": "Online or on-site review focused on reversible adjustments."}, {"title": "Action list", "body": "A clear, prioritised list of non-structural suggestions."}]'::jsonb,'["No demolition or construction cost", "Suggestions suitable for rented or shared spaces", "Changes can be made gradually and reversed if needed"]'::jsonb,'["Outcomes are not guaranteed", "Some layout features cannot be addressed without structural change, and this is stated plainly", "Not a substitute for safety, structural or legal advice"]'::jsonb,'[{"q": "What does non-invasive Vastu mean?", "a": "It means working with the existing structure: adjusting usage, placement, colours and arrangement rather than breaking or rebuilding anything."}, {"q": "Is it suitable for a rented flat?", "a": "Yes. It was designed for exactly this kind of situation, where structural change isn''t possible."}]'::jsonb,'Non-Invasive Vastu Without Demolition | Dr. Anameka S Panda','Non-invasive Vastu guidance for homes and offices: practical, reversible suggestions with no demolition or construction. Online and in-person consultations.',30,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('astro-vastu-integration','Astro-Vastu Integration','Your birth chart and your living space, read together, with non-invasive Vastu suggestions guided by your chart.','Sparkles','Astrology looks at you; Vastu looks at your space. Astro-Vastu Integration brings the two together, so suggestions for your home or workplace take your own chart into account. In Anameka''s words: the stars align, your space aligns, you align.','An integrated consultation that combines a Vedic astrology reading with a Vastu review of your home or workplace. Suggestions are non-invasive and need no structural changes.','Your birth chart is prepared and your floor plan reviewed in advance. The consultation looks at both together and focuses on the areas of life you want to work on, such as health, career, relationships or peace of mind.','People who want guidance on both their own timing and their living or working space, especially when moving home, renovating or starting a business.','[{"title": "Share details", "body": "Birth details plus a floor plan with north marked and photographs."}, {"title": "Preparation", "body": "Chart and plan are studied together."}, {"title": "Consultation", "body": "Online or in person, focused on your priorities."}, {"title": "Suggestions", "body": "Prioritised, non-structural adjustments and optional remedies."}]'::jsonb,'["One consultation covering both chart and space", "No demolition or structural changes needed", "Suggestions linked to the areas of life you care about"]'::jsonb,'["Astrology and Vastu are traditional systems; outcomes are not guaranteed", "Not a substitute for structural, medical, legal or financial advice"]'::jsonb,'[{"q": "What is Astro-Vastu?", "a": "An approach that reads your birth chart and your home or workplace together, so Vastu suggestions take your chart into account."}, {"q": "Will I need to make structural changes?", "a": "No. Suggestions are non-invasive and work with your existing space."}]'::jsonb,'Astro-Vastu Integration Consultation | Dr. Anameka S Panda, Bhubaneswar','Vedic astrology and non-invasive Vastu read together: your chart and your space aligned, with no structural changes. Online or in Bhubaneswar.',40,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('graphology','Graphology (Handwriting & Signature Analysis & Therapy)','Comprehensive diagnostic handwriting and signature analysis paired with guided graphotherapy strokes for subconscious transformation, focus, and emotional harmony.','PenLine','Handwriting and signatures are direct neuro-muscular projections of the subconscious mind. Graphology (Handwriting & Signature Analysis & Therapy) combines in-depth diagnostic analysis of pen strokes, margins, slants, and pressure with targeted graphotherapy exercises to dissolve emotional blocks, cultivate inner confidence, and align external behavior.','A complete three-stage subconscious framework: Stage 1 evaluates baseline handwriting strokes (thought patterns, emotional stability, stress handling). Stage 2 decodes signature geometry (public persona, executive authority, self-worth). Stage 3 prescribes custom graphotherapy drills—re-training hand movements to reprogram subconscious habits, improve exam focus, and anchor positive personality shifts.','You provide a sample of natural handwriting on unruled paper alongside your everyday signatures. Dr. Anameka conducts an in-depth audit, discusses subconscious patterns in a private consultation, and prescribes tailored corrective exercises practised over 21 to 30 days.','Students seeking academic focus and exam calm, professionals and leaders refining their executive presence, teachers understanding student emotional states, and individuals pursuing subconscious self-mastery.','[{"title": "Sample Submission", "body": "Half a page to a page of natural unruled handwriting and 5 regular signatures using your everyday pen."}, {"title": "Comprehensive Diagnostic Audit", "body": "In-depth review of stroke zones, slants, pressure, spacing, margins, and signature dynamics."}, {"title": "Therapeutic Stroke Prescription", "body": "Customized graphotherapy exercises and signature refinement guidelines practised over 21 to 30 days."}, {"title": "Progress & Review", "body": "Periodic sample comparison to measure subconscious behavioral integration and emotional shifts."}]'::jsonb,'["Unified diagnosis and corrective therapy in a single consultation roadmap", "Non-invasive, practical neuro-muscular habit transformation", "No birth date or horoscope required—pure subconscious science"]'::jsonb,'["Graphotherapy requires consistent daily practice (5-10 minutes) for permanent behavioral results", "Complements psychological and medical care; not a substitute for clinical psychiatric treatment"]'::jsonb,'[{"q": "How does changing handwriting or signature change my mind?", "a": "Handwriting is brainwriting—conducted via subconscious neural pathways. Consciously practicing specific therapeutic strokes (Graphotherapy) sends reverse bio-feedback to neural pathways, calming anxiety, sharpening focus, and reinforcing confidence over 21-30 days."}, {"q": "Does this consultation include both handwriting and signature?", "a": "Yes! Dr. Anameka evaluates your natural handwriting sample, analyzes your signature dynamics, and provides corrective graphotherapy exercises in one complete integrated session."}, {"q": "Can children and students benefit from this?", "a": "Absolutely. It is the cornerstone of Dr. Anameka''s work with students and educators, helping children overcome exam resistance, restlessness, and lack of concentration without pressure."}]'::jsonb,'Graphology (Handwriting & Signature Analysis & Therapy) | Dr. Anameka S Panda','Comprehensive Graphology with Dr. Anameka S Panda: handwriting diagnosis, signature analysis, and corrective graphotherapy for subconscious confidence and focus.',50,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('watch-correction','Wrist Watch Analysis and Therapy','Deep diagnostic analysis of your wristwatch: dial shape, metals, colors, and therapeutic wearing rules for career, wealth, and subconscious alignment.','Watch','Your wristwatch is not just a timekeeper; it is an intimate energetic instrument worn against your pulse points. Wrist Watch Analysis and Therapy evaluates how dial geometry, hands, numerical fonts, metals, and wrist placement influence your subconscious time perception, punctuality, and financial momentum.','In-depth analysis of your existing wristwatches, followed by personalized therapeutic recommendations. Guidance covers optimal wrist placement (dominant vs. receptive), dial geometry (round, square, tonneau), metallic frequencies, color resonance, and strap material to align with your astrological charts and life ambitions.','Conducted either as a standalone diagnostic consultation or integrated with your Vedic astrology and numerology charts.','Entrepreneurs, professionals, and students seeking to overcome procrastination, improve financial flow, and harmonize their daily energetic rhythm.','[{"title": "Watch & Photo Audit", "body": "Share photographs of your current wristwatches (dial, back, strap) along with your birth date and dominant hand."}, {"title": "Therapeutic Prescription", "body": "Detailed evaluation and tailored recommendations on corrective dials, colors, wearing wrist, and timing."}]'::jsonb,'["Non-invasive subconscious alignment through everyday timepieces", "Enhanced punctuality, decision-making clarity, and focus", "No compulsory purchases—guidance prioritizes optimizing watches you already own"]'::jsonb,'["A holistic energetic therapy designed to complement conscious personal discipline", "You are never pressured into buying proprietary branded products"]'::jsonb,'[{"q": "Do I have to buy an expensive new watch for this therapy?", "a": "Not at all. In most cases, therapy focuses on adjusting how, when, and on which wrist you wear your existing collection. If a new watch is ever recommended, budget-friendly options that meet the energetic parameters are suggested."}, {"q": "How does a wristwatch affect our psychology and success?", "a": "A wristwatch constantly touches vital meridian points on your wrist and is repeatedly glanced at dozens of times a day. Its shapes, colors, and movement directly anchor subconscious time-urgency and decision-making habits."}]'::jsonb,'Wrist Watch Analysis and Therapy | Dr. Anameka S Panda','Wrist Watch Analysis and Therapy with Dr. Anameka S Panda: holistic evaluation of dial geometry, colors, metals, and wrist placement for career and subconscious harmony.',60,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('logo-design-guidance','Scientific Logo Designing','Vibrational brand engineering aligning sacred geometry, 5-element color frequencies, font stroke psychology, and founder astrology.','Shapes','A logo is far more than a decorative visual—it is the energetic signature and subconscious beacon of your entire enterprise. Scientific Logo Designing integrates sacred geometry, the five elemental frequencies (Pancha Mahabhutas), graphological font movement, and founder astrological resonance to engineer brand marks that inspire customer trust and sustain commercial prosperity.','A rigorous scientific evaluation and design blueprint examining 5 foundational dimensions: angular trajectory (ascending growth vs. energy leaks), geometric balance (circles, shields, polygons), elemental color spectrums (activating wealth and stability), typography strokes, and harmony with the business owners'' astrological charts.','Share your current logo, proposed concepts, or begin from scratch with founder birth details and business objectives. Dr. Anameka provides exact energetic guidelines, chromatic specifications, and directional mockups for your design team.','Founders launching a new enterprise, corporate leaders planning a high-impact rebrand, and agencies designing for discerning commercial clients.','[{"title": "Brand & Founder Energy Audit", "body": "Analysis of business domain, founder birth details, and existing branding concepts."}, {"title": "Geometric & Chromatic Blueprint", "body": "Exact specifications on shapes, directional angles, font psychology, and elemental colors."}, {"title": "Design Alignment & Final Review", "body": "Review of finalized vectors created by your design team to ensure complete scientific compliance."}]'::jsonb,'["Scientifically engineered brand identity that anchors trust and commercial pull", "Harmonization between the enterprise energy and founder astrological strengths", "Clear, actionable design guidelines that any graphic designer or creative agency can easily execute"]'::jsonb,'["Scientific logo design creates energetic alignment; operational and market excellence remain essential", "Trademark registration and formal legal clearances should be conducted with legal counsel"]'::jsonb,'[{"q": "How is Scientific Logo Designing different from regular graphic design?", "a": "Graphic design focuses primarily on aesthetic appeal. Scientific Logo Designing looks beneath aesthetics—evaluating subtle subconscious energy flows, elemental colors, geometric balance, and astrological compatibility to ensure the mark actively supports growth rather than scattering energy."}, {"q": "Do you provide ready vector files or guidelines for our designer?", "a": "Dr. Anameka provides the detailed scientific blueprint, exact Pantone color codes, geometric angle ratios, and directional sketches. Your creative designer or agency uses this blueprint to finalize high-resolution vector files."}]'::jsonb,'Scientific Logo Designing | Brand Vibrations & Energy Alignment | Dr. Anameka S Panda','Scientific Logo Designing with Dr. Anameka S Panda: optimize brand geometry, elemental colors, stroke psychology, and astrological harmony for commercial prosperity.',70,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('mobile-number-analysis','Numerology Consultation (Mobile, Vehicle, Account & Business)','Comprehensive vibrational analysis of all significant numbers: mobile number, bank account, vehicle/car number, flat number, and date of birth.','Hash','Numbers carry distinct vibrational frequencies that continually interact with your subconscious mindset and external opportunities. Numerology Consultation analyzes every crucial number in your life—including your mobile phone, bank account, vehicle/car registration, home/flat address, and business contact numbers—aligning them with your date of birth (Mulank & Bhagyank) for sustained prosperity.','A 360-degree diagnostic evaluation covering: 1) Mobile Number Numerology (calling energy and opportunity flow), 2) Bank Account Number (financial retention, liquidity, and wealth stability), 3) Vehicle / Car Registration (transit harmony, safety, and smooth travels), 4) House & Office Flat Numbers (environmental numerical resonance), and 5) Name & Date of Birth Harmony (Mulank & Bhagyank planetary alignment).','Provide your date of birth alongside the numbers you wish to evaluate (current mobile numbers, bank accounts, car plates, flat addresses, or shortlists of options). Dr. Anameka calculates compound frequencies and provides practical alignment recommendations.','Entrepreneurs, car owners, professionals selecting new phone/bank numbers, and anyone seeking to align their daily numerical vibrations with their birth chart.','[{"title": "Share Numbers & Date of Birth", "body": "Your date of birth along with current or shortlisted numbers (mobile, car, bank account, or flat)."}, {"title": "Frequency & Grid Audit", "body": "Comprehensive compound calculations, planetary number affinities, and missing number checks."}, {"title": "Harmonization & Remedies", "body": "Practical recommendations on optimal numbers to choose and remedies to harmonize existing fixed numbers."}]'::jsonb,'["Holistic guidance covering mobile, vehicle, bank, and residential numbers in one session", "Clear, mathematically grounded selection criteria for new numbers", "Practical neutralization remedies for numbers you cannot change (e.g. car or bank accounts)"]'::jsonb,'["Numerology provides vibrational alignment; personal effort and practical decision-making remain paramount", "Changing official numbers entails administrative steps that should be weighed independently"]'::jsonb,'[{"q": "Can I get my car and bank account numbers checked in this consultation?", "a": "Yes! The consultation covers mobile numbers, vehicle registration numbers, bank account numbers, and home/office addresses alongside your personal birth numerology."}, {"q": "What if I cannot change my bank account or vehicle number?", "a": "You do not always need to change a number. Dr. Anameka provides simple numerical neutralization remedies (like lucky frequency pairing, signature codes, or color associations) to harmonize existing numbers."}]'::jsonb,'Numerology Consultation (Mobile, Vehicle, Account & Business) | Dr. Anameka S Panda','Numerology consultations with Dr. Anameka S Panda: analyze mobile numbers, vehicle & car numbers, bank accounts, and address vibrations in Bhubaneswar and online.',80,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('remedial-measures','Remedial Measures','No-fear, practical traditional remedies such as mantras, rituals and, where appropriate, gemstones, suggested within a full consultation.','Flame','Remedial measures are traditional practices suggested after an astrology or Vastu consultation. Dr. Anameka favours remedies that are simple, affordable and fit into daily life.','Remedies can include mantras, simple rituals, charitable acts, routines, colour or placement suggestions and, where appropriate, gemstones. Anameka''s approach is no-fear and practical: remedies are offered as optional supports to your own reflection and effort, never as threats or substitutes for them.','Remedies are always discussed in context, with the reasoning explained. You are free to adopt, adapt or decline any suggestion.','Clients who have had an astrology or Vastu consultation and want practical, traditional steps to accompany their own efforts.','[{"title": "Consultation", "body": "Remedies follow from a full consultation, not in isolation."}, {"title": "Suggestions", "body": "A short list of practices, with how and when to follow them."}, {"title": "Review", "body": "Optional follow-up to discuss how the practices fit your routine."}]'::jsonb,'["Simple practices that fit into daily routines", "No pressure to buy expensive items"]'::jsonb,'["Remedies are traditional practices; outcomes are not guaranteed", "Never stop medical treatment or ignore professional advice in favour of a remedy"]'::jsonb,'[{"q": "Do remedies require buying gemstones or costly items?", "a": "No. The emphasis is on simple, affordable practices. Any purchase is optional and your decision."}, {"q": "Can remedies replace medical treatment?", "a": "No. Always follow the advice of your doctor or other qualified professionals."}]'::jsonb,'Remedial Measures | Dr. Anameka S Panda','Simple, practical traditional remedies suggested within a full astrology or Vastu consultation. Affordable, optional and explained clearly.',90,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('medical-astrology-vastu','Medical Astrology / Vastu','Diagnostic analysis of planetary health root causes in the birth chart combined with North-North-East healing zone Vastu harmonization.','HeartPulse','Physical health is deeply intertwined with cosmic planetary vibrations and the environmental energies of your dwelling. Medical Astrology / Vastu diagnoses subtle astrological indicators in the 6th, 8th, and 12th houses of your Janam Kundli, while balancing the North-North-East (Arogya) directional zone of your home to support vital immunity, rapid recovery, and physical well-being.','A dual-lens synthesis: Medical Astrology investigates planetary afflictions affecting specific bodily systems (e.g., Sun for vitality and heart, Moon for fluids and mental calm, Mars for blood and inflammation, Saturn for chronic strain), while Health Vastu identifies and clears environmental geopathic stress, toilets, or clutter in the healing zones of your residence.','Provide your birth details (date, time, place) alongside a floor plan of your home with North indicated. Dr. Anameka evaluates the energetic correlations and offers non-invasive remedial adjustments. This holistic guidance works alongside, and never replaces, professional medical diagnosis and treatment.','Individuals and families experiencing persistent lethargy, unexplained recurring health setbacks, prolonged recovery periods, or seeking preventive energetic harmony for family members.','[{"title": "Birth Chart Health Audit", "body": "Detailed assessment of the 6th house (Roga), Lagna lord vitality, and active planetary Dasha periods."}, {"title": "Premises Health Zone Check", "body": "Examination of North-North-East (NNE - Health & Healing) and South-South-West zones for energetic disturbances."}, {"title": "Holistic Remedial Prescription", "body": "Non-invasive color adjustments, elemental stabilizers, gemstone/mantra recommendations, and bed direction alignment."}]'::jsonb,'["Identifies subtle astrological predispositions before chronic manifestation", "Harmonizes home healing zones without demolition or expensive structural changes", "Supports conventional medical care by removing energetic and environmental recovery barriers"]'::jsonb,'["Medical Astrology and Health Vastu are holistic energetic disciplines; they are never a substitute for qualified medical care, diagnosis, or prescribed treatments", "You must never stop or alter any ongoing medical therapy or medication"]'::jsonb,'[{"q": "Does Medical Astrology replace visiting a doctor?", "a": "Never. Dr. Anameka strictly emphasizes that astrological and Vastu insights serve as complementary energetic support. Always consult qualified doctors and medical specialists for all health conditions."}, {"q": "How does Vastu affect physical health?", "a": "In Vastu Shastra, the North-North-East (NNE) direction governs immunity and healing, while the East governs vitality. Disturbances like toilets, heavy clutter, or fire elements in these zones can energetically stall recovery."}]'::jsonb,'Medical Astrology & Health Vastu Consultation | Dr. Anameka S Panda','Medical Astrology and Health Vastu consultations with Dr. Anameka S Panda: analyze planetary health indicators and harmonize home healing zones in Bhubaneswar and online.',100,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('business-growth-guidance','Business Growth Guidance','A combined perspective on your business using astrology, Vastu, naming and branding guidance.','TrendingUp','Business owners often bring several questions at once: timing a launch, setting up premises, choosing a name or logo. This service brings Dr. Anameka''s disciplines together into one consultation for your business.','Depending on your needs, guidance may draw on Vedic astrology for timing, Vastu for premises, and review of names, logos and numbers. It complements, and never replaces, professional financial, legal and strategic advice.','An intake conversation identifies the decisions you are facing. Relevant analyses are prepared and brought together in one consultation.','Founders, family businesses, shop owners and professionals planning launches, relocations or rebrands.','[{"title": "Intake", "body": "Describe your business and the decisions ahead."}, {"title": "Preparation", "body": "Relevant charts, plans and brand materials are reviewed."}, {"title": "Consultation", "body": "A combined session covering each area."}, {"title": "Notes", "body": "A summary of observations and suggestions."}]'::jsonb,'["One consultation that brings several perspectives together", "Useful before major commitments such as premises or branding"]'::jsonb,'["Business outcomes depend on many factors and are not guaranteed", "Does not replace financial, legal, tax or strategic professional advice"]'::jsonb,'[{"q": "Can this replace a business consultant or accountant?", "a": "No. It is a complementary perspective. Always consult qualified financial, legal and tax professionals for those matters."}]'::jsonb,'Business Growth Guidance | Dr. Anameka S Panda','Business guidance combining Vedic astrology, Vastu, and name and logo review for founders and business owners. Complements professional advice.',110,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('aura-scanning-cleansing','Aura Scanning & Cleansing','Discover your energetic state in minutes. Release subtle blockages and restore pure vibrational flow.','Sparkles','Aura scanning evaluates the subtle electro-magnetic and bio-energetic field surrounding your physical body. It identifies stress pockets, energetic stagnation, and auric leaks, followed by structured vibrational cleansing.','Every living being emits a subtle energetic field influenced by emotions, stress, physical wellness, and environmental vibrations. When this field collects dense vibrations, individuals feel depleted, anxious, or ungrounded. Cleansing re-harmonizes the auric layers.','Dr. Anameka reads your bio-energetic auric profile, identifies imbalances across emotional and mental energy sheaths, and guides you through restorative cleansing protocols.','Those feeling persistent fatigue, heavy emotions, recurring setbacks without medical cause, or seeking deep energetic clarity and spiritual protection.','[{"title": "Intake & Baseline Check", "body": "Discuss your current life context, fatigue patterns, and emotional stressors."}, {"title": "Energy Field Scanning", "body": "Identify stagnant energy patches, auric tears, or congested chakric points."}, {"title": "Frequency Cleansing", "body": "Gentle energetic sweeps, sound frequencies, and vibrational harmonization."}, {"title": "Protective Sealing & Guidance", "body": "Simple daily hygiene practices to shield your personal aura from absorbing external stress."}]'::jsonb,'["Feel noticeably lighter, calmer, and more centered", "Clear stagnant negative thought forms and heavy external energies", "Available in-person or via focused distance alignment worldwide"]'::jsonb,'["Spiritual and energetic practices complement but do not replace medical or psychological care", "Individual sensory experiences during energetic cleansing vary"]'::jsonb,'[{"q": "Can aura scanning be done online or from a distance?", "a": "Yes. Energetic resonance and auric diagnostics can be conducted effectively via virtual consultation and distance evaluation."}, {"q": "How will I feel after an aura cleansing session?", "a": "Clients typically describe feeling as though a heavy mental weight has been lifted, experiencing lighter thoughts, deeper calm, and renewed vitality."}, {"q": "Is any physical contact required?", "a": "None whatsoever. It is a completely non-invasive vibrational evaluation."}, {"q": "How often should I get my aura cleansed?", "a": "Most clients benefit from seasonal or quarterly check-ins, or whenever navigating major life transitions or high-stress environments."}]'::jsonb,'Aura Scanning & Cleansing Therapy | Dr. Anameka S Panda','Identify subtle energetic blockages and cleanse your personal bio-energy field with Dr. Anameka S Panda. Feel lighter, think clearer, and attract positive abundance.',120,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('reiki-healing','Reiki Healing Therapy','Distant and hands-on energy restoration to dissolve stress, restore vitality, and rebalance inner life force.','HeartPulse','Reiki is an ancient vibrational healing modality based on the principle that universal life force energy (Prana) flows through all living beings. When life force energy is depleted, we feel tired, stressed, or emotionally fragile. Reiki replenishes this vital reservoir.','A meditative practice where the practitioner channels Universal Life Energy to dissolve energetic blockages, calm the sympathetic nervous system, and restore natural equilibrium across physical, mental, and spiritual layers.','Conducted in a tranquil, receptive atmosphere either in-person or across distance worldwide. The session focuses on full-body energetic sweeps and concentrated focus on fatigued energy centers.','Individuals experiencing chronic stress, emotional heartbreak, burnout, sleep disturbance, or those seeking deep inner peace and cellular relaxation.','[{"title": "Intention & Consultation", "body": "Identify the primary physical, emotional, or mental priorities you wish to address."}, {"title": "Receptive Relaxation", "body": "You relax comfortably while energy channeling begins across your major energetic nodal centers."}, {"title": "Blockage Release & Sweep", "body": "Concentrated channeling to break up energetic knots and restore smooth prana flow."}, {"title": "Integration & Grounding", "body": "Gentle awakening and grounding guidance to anchor the restorative energy into daily life."}]'::jsonb,'["Deep somatic relaxation and nervous system down-regulation", "Enhanced emotional resilience, peaceful sleep, and reduced stress", "100% non-invasive; distance healing available worldwide"]'::jsonb,'["Reiki is a complementary holistic practice and does not diagnose, treat, or cure medical diseases"]'::jsonb,'[{"q": "Does distance Reiki work as effectively as in-person sessions?", "a": "Yes. In quantum and spiritual energy traditions, life force energy transcends physical distance. Distance sessions produce equally profound relaxation and energetic rebalancing."}, {"q": "What should I do during a distance session?", "a": "Simply rest in a quiet, undisturbed space lying down or comfortably seated, wearing comfortable clothes."}, {"q": "Is Reiki affiliated with any religion?", "a": "No. Reiki is a universal spiritual wellness science open to individuals of all faiths and backgrounds."}]'::jsonb,'Reiki Healing & Energy Balancing | Dr. Anameka S Panda','Restore your vital life force with personalized in-person and distant Reiki healing sessions by Dr. Anameka S Panda. Dissolve stress and revitalize your spirit.',130,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('crystal-healing-therapy','Crystal Healing Therapy','Harness the vibrational frequencies of energized, programmed gemstones to amplify healing and manifest intentions.','Gem','Natural gemstones and crystals carry exceptionally stable crystalline molecular lattice structures. In Crystal Healing Therapy, specific mineral gems are selected, cleansed, and energetically aligned with your astrological planetary influences and chakras.','A traditional vibrational science that pairs the electromagnetic resonance of minerals with human energy centers. Crystals act as natural resonators to absorb negativity, amplify noble thoughts, and ground erratic emotions.','Dr. Anameka examines your planetary chart and energetic needs to prescribe specific gemstones, sacred grid layouts, or personal crystals programmed with specific affirmations.','Those seeking energetic grounding, protection from toxic atmospheres, emotional healing, prosperity attraction, or harmonious planetary gemstone remedies.','[{"title": "Chart & Energy Diagnostic", "body": "Evaluate your natal planetary strengths and current energy challenges."}, {"title": "Mineral & Gem Selection", "body": "Identification of authentic, certified gemstones suited specifically to your aura."}, {"title": "Cleansing & Programming", "body": "Energetic purification and attunement with Vedic mantras and sacred intentions."}, {"title": "Wearing & Placement Protocol", "body": "Specific timings, finger placements, or room coordinates for maximum resonance."}]'::jsonb,'["Personalized to your unique birth chart and energetic signature", "Natural, non-invasive metaphysical grounding and protective shielding", "Practical guidelines for cleansing, wearing, and space placement"]'::jsonb,'["Crystals and gemstones are energetic amplifiers and spiritual tools, not guarantees of wealth or medical miracles"]'::jsonb,'[{"q": "How do I know which gemstone or crystal is right for me?", "a": "Choosing crystals based solely on aesthetics or general sun-signs can sometimes agitate incompatible planetary energies. Dr. Anameka analyzes your precise birth chart and aura before recommending any gem."}, {"q": "Do crystals need to be cleansed regularly?", "a": "Yes. Natural crystals absorb ambient energies and benefit from periodic cleansing through water, sunlight, moonlight, or sound resonance."}]'::jsonb,'Crystal Healing Therapy & Gemstone Resonance | Dr. Anameka S Panda','Align your energy with authentic crystal healing therapy and astrological gemstone programming by Dr. Anameka S Panda.',140,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('chakra-balancing','Chakra Balancing & Cleansing','Release emotional and energetic blockages across the seven core energy vortexes to restore natural flow and vitality.','Sun','The human subtle energy body is governed by seven primary energy vortexes (chakras) aligning along the cerebrospinal axis. When these centers become choked by suppressed grief, fear, or overthinking, life feels stagnated.','An ancient yogic and esoteric science of inspecting the rotation, vibrancy, and openness of the Muladhara, Swadhisthana, Manipura, Anahata, Vishuddha, Ajna, and Sahasrara chakras.','Through diagnostic intuitive reading, acoustic sound frequencies, and breathwork guidance, Dr. Anameka identifies under-active and over-active vortexes, bringing them into harmonious coherence.','Anyone feeling blocked in self-expression, struggling with irrational fears or money blocks, carrying deep relationship wounds, or seeking spiritual clarity.','[{"title": "Chakra Resonance Scan", "body": "Locate which of the 7 vortexes are depleted, congested, or misaligned."}, {"title": "Emotional Residue Release", "body": "Clear stagnant emotional memories stored within specific nerve plexuses."}, {"title": "Vibrational Alignment", "body": "Restore clockwise spin, balance, and color resonance through targeted focus."}, {"title": "Anchoring Mantras & Habits", "body": "Simple daily breathwork and seed syllables (Bija Mantras) to maintain alignment."}]'::jsonb,'["Restores balance between emotional, mental, and physical vitality", "Dissolves subconscious resistance around self-worth, communication, and trust", "Leaves you feeling anchored, clear-headed, and energized"]'::jsonb,'["Chakra work is a meditative spiritual practice and does not substitute for mental health counseling"]'::jsonb,'[{"q": "How do I know if my chakras are unbalanced?", "a": "Common symptoms include unexplained lethargy, sudden emotional swings, fear of public speaking (Throat), constant financial anxiety (Root), or inability to forgive past hurt (Heart)."}, {"q": "Can chakra alignment be experienced remotely?", "a": "Yes. Remote sessions utilize guided intention, frequency focus, and personalized breath guidance with equal potency."}]'::jsonb,'Chakra Balancing & Cleansing Consultation | Dr. Anameka S Panda','Unlock your seven vital energy centers with professional chakra balancing and cleansing by Dr. Anameka S Panda. Clear emotional blockages and restore your inner spark.',150,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('total-energy-alignment','Total Energy Alignment','An integrated diagnostic and complete reset for Health, Wealth, and Relationships across your chart, space, and auric field.','Activity','When obstacles occur simultaneously across career, family harmony, and physical vitality, addressing only one isolated symptom is seldom sufficient. Total Energy Alignment is Dr. Anameka S Panda’s signature master synthesis of Jyotish astrology, Non-Invasive Vastu, and Bio-Energy Cleansing.','A comprehensive tri-pillar diagnostic that evaluates: (1) Your planetary timing in the Vedic cosmos, (2) The geometric energy flow of your dwelling or workplace, and (3) Your personal auric and subconscious frequency.','A multi-dimensional consultation that diagnoses where energy is leaking or blocked across your Health, Wealth, and Relationship spheres, followed by a prioritized roadmap of practical corrections.','Individuals, couples, and entrepreneurs seeking a definitive, holistic breakthrough across health, wealth, and relationship harmony without conflicting piecemeal remedies.','[{"title": "Tri-Dimensional Intake", "body": "Submission of your birth data, residential/office floor plan, and personal challenges."}, {"title": "Unified Master Diagnosis", "body": "In-depth cross-referencing of planetary dashas, spatial Vastu zones, and auric blockages."}, {"title": "Harmonization Consultation", "body": "A comprehensive session reviewing root causes and providing exact, non-invasive remedies."}, {"title": "30-Day Alignment Roadmap", "body": "Step-by-step guidance to anchor long-term health, financial abundance, and domestic peace."}]'::jsonb,'["Complete holistic coverage: simultaneously balances Health, Wealth, and Relationships", "Harmonizes chart, living space, and personal aura in unified alignment", "100% practical, non-destructive, with distant sessions available worldwide"]'::jsonb,'["Requires genuine willingness to implement spatial and daily routine suggestions"]'::jsonb,'[{"q": "What makes Total Energy Alignment different from a standard astrology reading?", "a": "A standard reading only identifies planetary timing. Total Energy Alignment also diagnoses your living space (Vastu) and clears your personal energetic field, giving you an end-to-end transformation."}, {"q": "Does this require knocking down walls or purchasing expensive statues?", "a": "Never. Dr. Anameka specializes strictly in non-invasive remedies: directional adjustments, color resonance, elemental balancing, and mindset alignment."}]'::jsonb,'Total Energy Alignment (Health, Wealth & Relationships) | Dr. Anameka S Panda','Experience Dr. Anameka S Panda’s flagship Total Energy Alignment consultation. Harmonize your birth chart, living space, and auric field for lasting health, wealth, and harmony.',160,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('student-inner-excellence','Student Inner Excellence Program','Class 8 to College Students, Competitive Exam Aspirants & Interview Candidates','students','Build Unshakeable Focus, Master the Mind & Clear Competitive Exams','A complete subconscious coaching programme for students from Class 8 onwards, competitive exam aspirants (JEE, NEET, UPSC, Banking, CA), and interview candidates. Blends mindset mastery, graphotherapy, and emotional resilience.','Academic success is 20% syllabus and 80% mindset. Whether preparing for high school finals, intense competitive entrances (NEET, JEE, UPSC, Banking), or high-stakes job interviews, students face procrastination, mental fatigue, self-doubt, and exam fear. Through personalized handwriting analysis (graphology), subconscious rewiring, and practical focus rituals, Dr. Anameka guides students to peak mental performance and composure under pressure.','[{"title": "Unshakeable Confidence", "body": "Overcome fear of failure, imposter syndrome, and perform with poise in exams and interviews."}, {"title": "Laser Focus & Memory", "body": "Master active recall, eliminate digital distractions, and sustain deep concentration."}, {"title": "Subconscious Alignment", "body": "Reprogram limiting beliefs through daily scientific graphotherapy and breathwork."}]'::jsonb,'[{"title": "Scientific Handwriting & Graphotherapy", "body": "Custom penmanship strokes to rewire patience, precision, and cognitive endurance."}, {"title": "Competitive Exam & Interview Mindset", "body": "Strategies to eliminate panic, handle tricky papers, and project authentic authority in interviews."}, {"title": "Memory Retention & Smart Study Habits", "body": "Techniques for high-yield revision without burnout."}, {"title": "Emotional Regulation & Stress Detox", "body": "Techniques to neutralize pressure from peers, mentors, and parents."}, {"title": "Parent & Mentor Alignment", "body": "Guidance sessions for families to foster a supportive, pressure-free sanctuary."}]'::jsonb,'["Students from Class 8 through university preparing for academic milestones", "Competitive exam aspirants (JEE, NEET, UPSC, State PCS, Banking, CLAT, CA)", "Graduates and job seekers preparing for high-stakes interviews and group discussions", "Students experiencing procrastination, anxiety, low retention, or lack of direction", "Parents seeking proven, pressure-free mentorship for their children"]'::jsonb,'One-to-one personalized mentoring sessions, online (live video) or in person, with periodic milestone evaluations.',null,null,'Enquire for Mentorship','INNER EXCELLENCE',null,null,'[{"q": "Which students can join this programme?", "a": "It is open to students from Class 8 onwards, college students, aspirants appearing for competitive entrance exams (JEE, NEET, UPSC, Banking, CA), and job interview candidates."}, {"q": "How does handwriting therapy help in competitive exams?", "a": "Handwriting therapy (graphotherapy) directly alters neural pathways associated with patience, analytical speed, and concentration span, preventing impulsive mistakes during timed exam conditions."}, {"q": "Are parents involved in the sessions?", "a": "Yes. Parent guidance sessions are integrated to help families reduce household tension and build an encouraging study sanctuary at home."}]'::jsonb,'Student Inner Excellence Program | Competitive Exams & Mindset | Dr. Anameka S Panda','Subconscious coaching for students from Class 8 onwards, competitive exam aspirants (JEE, NEET, UPSC, Banking), and interview candidates. Online and in Bhubaneswar.',10,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('exam-ready-from-the-inside','Exam Ready From the Inside','Class 10 & 12 Board Exam Students (CBSE, ICSE, State Boards) & Parents','students','Turn Board Exam Stress into Calm, High-Speed Exam Hall Mastery','Specifically crafted for Class 10 and Class 12 board exam candidates. Combines handwriting graphotherapy, paper-writing stamina, and inner emotional steadiness so students write with speed, clarity, and zero blank-outs.','Tuition centres complete the syllabus, but they cannot stop the child''s hands from trembling or their mind from going blank when the board exam paper is placed on their desk. ''Exam Ready From the Inside'' specifically trains Class 10 and Class 12 students in the psychological and physiological aspects of board exam performance: neat high-speed handwriting, calm time management, and emotional poise.','[{"title": "Board Exam Composure", "body": "Banish the dreaded blank-out and walk into the board exam hall grounded, calm, and prepared."}, {"title": "High-Speed Legible Writing", "body": "Improve writing endurance so 3-hour long subjective papers are completed with ease."}, {"title": "Parental Peace of Mind", "body": "Eliminate household tension during board exam months with supportive daily routines."}]'::jsonb,'[{"title": "Targeted Graphotherapy for Exam Stamina", "body": "Daily penmanship drills to relieve wrist fatigue and enhance presentation clarity for board examiners."}, {"title": "The 3-Hour Paper Strategy", "body": "Techniques for the first 15 minutes of reading time, question pacing, and error-checking."}, {"title": "Spiritual Daily Rhythm", "body": "Brief morning and pre-sleep grounding rituals to prevent panic and maintain mental freshness."}, {"title": "Parent Consultation & De-stressing Guide", "body": "Practical steps parents can take at home to keep the atmosphere relaxed."}]'::jsonb,'["Students preparing for Class 10 or Class 12 Board Exams (CBSE, ICSE, State Boards)", "Children who know the syllabus thoroughly but freeze, rush, or blank out in exams", "Students struggling with slow writing speed or messy presentation losing easy marks", "Parents who want to support their board student without adding more pressure"]'::jsonb,'Begins with a diagnostic consultation for student and parents. Conducted online or in person.',null,null,'Book Board Exam Discovery Call','BOARD EXAM READY',null,null,'[{"q": "Is this a replacement for academic tuition?", "a": "No. It works alongside your child''s academic studies, focusing on psychological calm, handwriting endurance, speed, and confidence rather than syllabus content."}, {"q": "How much daily practice is required?", "a": "The daily graphotherapy practices take only 10 to 15 minutes and fit effortlessly into the student''s revision schedule."}, {"q": "How does it stop students from blanking out during board exams?", "a": "Blanking out is triggered by acute sympathetic nervous system fight-or-flight arousal. Through physiological breathing anchors and muscle-memory handwriting strokes, the student maintains parasympathetic composure."}]'::jsonb,'Exam Ready From the Inside | Class 10 & 12 Board Exam Mastery | Dr. Anameka S Panda','Specialized board exam coaching for Class 10 & 12 students combining graphotherapy handwriting speed, emotional calm, and exam hall strategy.',20,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('handwriting-mastery-certification','Handwriting Mastery Certification','Open to Everyone — Teachers, Homemakers, Principals, Professionals & Students','universal','Transform Penmanship, Subconscious Focus & Teaching Mastery','A comprehensive, universally accessible certification open to educators, homemakers, working professionals, school principals, and students. Master scientific handwriting mechanics, graphotherapy principles, and pedagogical guidance.','Handwriting is crystallized thought. How we hold a pen and shape our strokes influences neuro-pathways responsible for patience, memory, self-discipline, and emotional balance. Whether you are a teacher guiding 40 students, a school principal elevating classroom standards, a homemaker seeking a rewarding skill, a professional aiming for executive presence, or a student wanting neater, faster writing—this certification equips you with the complete science and art of handwriting mastery.','[{"title": "Cognitive Focus & Memory", "body": "Harness hand-brain coordination to heighten mental clarity, analytical thinking, and focus."}, {"title": "Flawless Speed & Aesthetics", "body": "Master ergonomic grip, rhythm, margin discipline, and effortless speed without hand fatigue."}, {"title": "Mentorship & Career Capability", "body": "Empower teachers and homemakers to start their own handwriting coaching or elevate institutional teaching."}]'::jsonb,'[{"title": "Scientific Anatomy of Writing", "body": "Stroke formation, pressure dynamics, baseline stability, and spacing psychology."}, {"title": "Universal Graphotherapy Applications", "body": "Recognizing signs of emotional distress, lethargy, or impulsivity in strokes and applying corrective exercises."}, {"title": "Pedagogy & Coaching Modules", "body": "Step-by-step guidance methods tailored for young children, teenagers, and adults."}, {"title": "Accredited Certification", "body": "Official certification awarded under the banner of Indian Vastu & Astrological Research Centre (Regd) & ISO 9001-2015 standards."}]'::jsonb,'["School teachers, tutors, and remedial educators", "Homemakers seeking self-development, personal enrichment, or home-coaching skills", "School principals and academic coordinators seeking campus-wide handwriting standards", "Working professionals and executives wanting poised, impactful handwriting and signatures", "College and school students looking to perfect their penmanship"]'::jsonb,'Flexible modular training available online (interactive live sessions) and in-person workshops, complete with practice manuals.',null,null,'Enquire to Enrol','CERTIFY',null,null,'[{"q": "Can homemakers and non-teachers take this certification?", "a": "Absolutely. The course is structured from fundamental penmanship biology to advanced coaching, making it ideal for homemakers, professionals, students, and educators alike."}, {"q": "Can an entire school or college staff enroll together?", "a": "Yes. Group institutional faculty training programs are conducted across Odisha and nationwide."}, {"q": "What accreditation does the certificate carry?", "a": "The certification is officially credentialed by Indian Vastu & Astrological Research Centre (Regd) with ISO 9001-2015 quality standards."}]'::jsonb,'Handwriting Mastery Certification | Teachers, Homemakers & Professionals | Dr. Anameka S Panda','Accredited Handwriting Mastery Certification for teachers, homemakers, principals, professionals, and students. ISO 9001-2015 certified.',30,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('teacher-handwriting-consultation','1-to-1 Handwriting & Subconscious Insight Consultation','Open to Everyone — Business Professionals, Homemakers, Job Seekers, Educators & Parents','universal','Uncover Hidden Subconscious Blocks, Career Strengths & Behavioural Roots Through Handwriting','A private, in-depth one-to-one consultation for individuals from all walks of life—business professionals, homemakers, job seekers, educators, and parents. Decode subconscious traits, emotional blocks, leadership patterns, and relationship dynamics through handwriting and signature analysis.','Your handwriting and signature are the direct mirror of your subconscious mind. Long before a behaviour, fear, hesitation, or talent shows up in daily life, it is already inscribed in your slants, loops, margins, and t-crosses. In this private 1-to-1 consultation, Dr. Anameka conducts an exhaustive analysis of your writing and signature, revealing your core strengths, unconscious emotional bottlenecks, decision-making style, and providing personalized graphotherapy remedies to unlock your true potential.','[{"title": "Subconscious Diagnosis", "body": "Identify underlying anxiety, trust issues, repressed frustration, or self-sabotage."}, {"title": "Career & Financial Blueprint", "body": "Understand financial mindset, negotiation traits, leadership presence, and public persona through your signature."}, {"title": "Actionable Graphotherapy", "body": "Receive bespoke stroke alterations to reprogram confidence, willpower, and inner peace."}]'::jsonb,'[{"title": "Comprehensive Sample Evaluation", "body": "Microscopic review of handwriting samples, baseline trends, spacing, pressure, and signature angles."}, {"title": "60-Minute Deep-Dive Consultation", "body": "One-on-one private discussion uncovering personality insights, career inclinations, and relationship tendencies."}, {"title": "Custom Graphotherapy Prescription", "body": "Tailored 21-day to 30-day penmanship therapy regimen to shift unconscious conditioning."}, {"title": "Post-Therapy Review", "body": "Follow-up check to monitor subconscious integration and visible shifts in daily demeanor."}]'::jsonb,'["Business owners and entrepreneurs seeking self-awareness, leadership confidence, and financial clarity", "Corporate professionals and job seekers preparing for career transitions or interviews", "Homemakers wanting personal clarity, emotional healing, and enhanced self-worth", "Educators and school teachers wanting deep insights into students'' hidden struggles and emotional needs", "Individuals experiencing recurring mental roadblocks, self-doubt, or relationship friction"]'::jsonb,'Confidential 1-to-1 session conducted via Zoom/Google Meet or in person at Bhubaneswar.',null,null,'Book Your 1-to-1 Consultation','ANALYZE',null,null,'[{"q": "What should I prepare for the consultation?", "a": "You will be asked to write an unlined page in your natural handwriting using a ballpoint pen and sign twice at the bottom, then send a clear photo or scan."}, {"q": "Can I consult about my child or spouse''s handwriting?", "a": "Yes. Parents and spouses frequently bring handwriting samples to understand emotional bottlenecks, communication gaps, or behavioural shifts."}, {"q": "Is the consultation completely confidential?", "a": "Strictly confidential. Your handwriting samples and personal discussions are never shared."}]'::jsonb,'1-to-1 Handwriting & Subconscious Insight Consultation | Dr. Anameka S Panda','Confidential 1-to-1 handwriting and signature analysis consultation for professionals, homemakers, job seekers, and educators. Decode subconscious traits and career blueprints.',40,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('child-script-coach','Child Script Coach™ Program','Teachers, Educators & Remedial Mentors','universal','See beyond the handwriting. See the child.','A specialized training programme that teaches educators and mentors to read handwriting as another lens for understanding and supporting each learner, leading to Child Script Coach certification.','Every student has a story, and sometimes their handwriting offers valuable clues. The Child Script Coach™ Program teaches educators the foundations of handwriting analysis so they can notice patterns early and respond to each child with more understanding.','[{"title": "Notice early", "body": "Identify learning and emotional patterns sooner."}, {"title": "Understand", "body": "See each child''s unique needs more clearly."}, {"title": "Connect", "body": "Build stronger teacher–student relationships."}]'::jsonb,'[{"title": "Foundations of handwriting analysis", "body": "Reading size, slant, pressure, spacing and letter forms in children''s writing."}, {"title": "Classroom application", "body": "Using what you observe to support confidence, engagement and growth."}, {"title": "Certification", "body": "On completion, become a certified Child Script Coach."}]'::jsonb,'["School teachers and educators", "Tutors and special-education support staff", "School leaders building pastoral-care skills"]'::jsonb,'Begins with a one-to-one discovery call. Online or in person.',null,null,'Book a Discovery Call','COACH',null,null,'[{"q": "Do I need any background in graphology?", "a": "No. The programme starts with the foundations."}, {"q": "Who awards the certification?", "a": "The Child Script Coach certification is awarded under the banner of Indian Vastu & Astrological Research Centre (Regd) on completion."}, {"q": "Is handwriting analysis a diagnostic tool?", "a": "No. It is a lens for observation and conversation, not a way to diagnose clinical conditions."}]'::jsonb,'Child Script Coach Program for Teachers & Educators | Dr. Anameka S Panda','Training for teachers in handwriting analysis as a lens for understanding students. Become a certified Child Script Coach.',50,'published') on conflict (slug) do nothing;
