insert into public.profile_sections (slug,title,body,verified,sort_order,status) values ('certifications','Certifications & Accreditation','<p><strong>A Unit of IVARC</strong><br/>Managed by: <strong>Indian Vastu &amp; Astrological Research Centre (Regd)</strong><br/><strong>ISO 9001-2015 Certified</strong></p><p>All consultation methodologies, esoteric research, and academy practitioner certifications are conducted under the quality-certified framework of the Indian Vastu &amp; Astrological Research Centre (Regd).</p>',true,60,'published') on conflict (slug) do nothing;
