insert into public.profile_sections (slug,title,body,verified,sort_order,status) values ('experience','Institutional Clients & Experience','<p>Dr. Anameka S Panda has over 15 years of dedicated practice spanning institutional student counseling, academic graphotherapy, and corporate energy alignment:</p><ul><li><strong>Indo Science Academy:</strong> Student Counsellor and Graphotherapist. Evaluated academic pressure, stress patterns, and concentration blocks in board and competitive exam students, prescribing targeted graphotherapy scripts for calm and focus.</li><li><strong>Ruchika Public School:</strong> Student counselor and graphology specialist. Conducted diagnostic penmanship camps, student emotional assessments, and faculty orientation sessions on recognizing subtle behavioral cues in student notebooks.</li><li><strong>Teacher & Educator Training:</strong> Conducts certified masterclasses via the <em>Child Script Coach™</em> and <em>Handwriting Mastery</em> initiatives for schools and coaching faculties.</li><li><strong>Corporate & Commercial Engagements:</strong> Conducted Scientific Logo Designing, premises Astro-Vastu alignment, and numerical frequency harmonizations for business founders, retail ventures, and professionals worldwide.</li></ul>',true,80,'published') on conflict (slug) do nothing;
insert into public.profile_sections (slug,title,body,verified,sort_order,status) values ('approach','Consultation approach','<p>Every consultation starts with your questions. Dr. Anameka prepares in advance, explains her observations in plain language, and offers suggestions that are practical and optional. Decisions always remain with the client.</p>',true,90,'published') on conflict (slug) do nothing;
